check.gd:
extends SceneTree
const Formation=preload("res://campaign/vehicles/convoy_formation_catalog.gd")
const Rules=preload("res://gameplay/sandbox_convoy_rules.gd")
const Factions=preload("res://battle/identity/faction_unit_catalog.gd")
const Config=preload("res://gameplay/sandbox_force_config.gd")
const Maps=preload("res://gameplay/sandbox_map_catalog.gd")
var errors=[]
var checks=0
var runs=[]
func _initialize():call_deferred("run")
func expect(ok: bool,label: String):
 checks+=1
 if not ok:errors.append(label);push_error(label)
func run():
 for faction in Factions.all_ids():
  var limit=4 if faction in ["stateline","blacktop","zangyaku","bitian","nbpd","trc"] else 2
  expect(Formation.two_wheelers_per_slot(faction)==limit,"Faction limit "+faction)
  var mixed=["ironhorse","bayou"]
  for i in range(limit-1):mixed.append("ironhorse")
  mixed.append("shuttle")
  var groups=Formation.slots(mixed,faction)
  expect(groups.size()==3 and groups[0].indices.size()==limit,"Nonconsecutive grouping "+faction)
  expect(Rules.check(mixed,16,faction).valid,"Mixed 16-seat convoy "+faction)
  var full=[]
  for i in range(limit*3):full.append("ironhorse")
  expect(Rules.check(full,limit*3,faction).valid,"Three full bike slots "+faction)
  expect(not Rules.addition(full,"ironhorse",16,faction).valid,"Fourth slot blocked "+faction)
  full.remove_at(0)
  expect(Rules.addition(full,"ironhorse",limit*3,faction).valid,"Removal restores availability "+faction)
  var pedal=[]
  for i in range(limit):pedal.append("yardbird")
  expect(Formation.slots(pedal,faction).size()==1,"Two-Wheelers category consistent "+faction)
  expect(not Rules.check(mixed,17,faction).valid,"16-unit cap "+faction)
  expect(not Rules.addition(["ironhorse"],"ironhorse",1,faction).valid,"No spare driver "+faction)
 var scene=load("res://gameplay/arsenal_review.tscn").instantiate();root.add_child(scene)
 for i in range(5):await process_frame
 scene.set_process(false)
 for variant in ["mercer","stateline","zangyaku","trc","twelve_bikes"]:
  for map in Maps.IDS:
   var faction="stateline" if variant=="twelve_bikes" else variant
   var c=Maps.preset(map);c.attacker.faction=faction;c.attacker.units=[];c.attacker.erase("vehicle_occupants")
   for i in range(16):c.attacker.units.append(Config.unit(Config.CLASSES[i%5]))
   c.attacker.vehicles=[]
   if variant=="twelve_bikes":
    for i in range(12):c.attacker.vehicles.append("ironhorse")
   else:
    c.attacker.vehicles=["ironhorse","bayou"]
    for i in range(Formation.two_wheelers_per_slot(faction)-1):c.attacker.vehicles.append("ironhorse")
    c.attacker.vehicles.append("shuttle")
   await scene.start_battle(false,c)
   var tag=variant+" / "+map
   expect(scene.battle!=null,"Launch "+tag+" "+scene.note.text)
   if scene.battle!=null:
    for i in range(12):await process_frame
    var b=scene.battle;var view=scene.runtime.get_node("TacticalBattleView");var people=[];var vehicles=[]
    for v in b.vehicles.values():
     if v.side_id==b.attacker_side_id:
      vehicles.append(v.battle_vehicle_id);people.append_array(v.get_meta("convoy_occupants",[]))
      expect(v.has_battle_position,"Placed vehicle "+tag+" "+v.battle_vehicle_id)
    var unique={}
    for id in people:unique[id]=true
    expect(vehicles.size()==c.attacker.vehicles.size(),"Every selected vehicle arrives "+tag)
    expect(people.size()==16 and unique.size()==16,"Every passenger exactly once "+tag)
    expect(view.battle_presentation.last_path_errors.is_empty(),"Dismount paths "+tag)
    runs.append({"variant":variant,"map":map,"vehicles":vehicles.size(),"passengers":people.size(),"path_errors":view.battle_presentation.last_path_errors})
   scene.return_to_setup();await process_frame
 var c=Maps.preset("river_bridge");c.defender.faction="bitian";c.defender.vehicles=[];c.defender.units=[]
 for i in range(12):c.defender.vehicles.append("ironhorse")
 for i in range(16):c.defender.units.append(Config.unit(Config.CLASSES[i%5]))
 await scene.start_battle(false,c)
 expect(scene.battle!=null,"Defending twelve-bike blockade "+scene.note.text)
 var result={"checks":checks,"errors":errors,"runs":runs}
 FileAccess.open("res://tools/bike_slots_20260915/check.json",FileAccess.WRITE).store_string(JSON.stringify(result,"\t"))
 print("BIKE_LIMIT_CHECK ",JSON.stringify(result));quit(0 if errors.is_empty() else 1)

ui.gd:
extends SceneTree
var errors=[]
var checks=0
var out="res://tools/bike_slots_20260915/"
func _initialize():call_deferred("run")
func expect(ok: bool,label: String):
 checks+=1
 if not ok:errors.append(label);push_error(label)
func click(control: Control):
 var at=control.get_global_transform_with_canvas()*(control.size*.5)
 var down=InputEventMouseButton.new();down.button_index=MOUSE_BUTTON_LEFT;down.button_mask=MOUSE_BUTTON_MASK_LEFT;down.pressed=true;down.position=at;down.global_position=at;root.push_input(down,true)
 var up=InputEventMouseButton.new();up.button_index=MOUSE_BUTTON_LEFT;up.position=at;up.global_position=at;root.push_input(up,true)
 await process_frame;await process_frame
func shot(name: String):
 for i in range(5):await process_frame
 await RenderingServer.frame_post_draw
 root.get_texture().get_image().save_png(out+name+".png")
func run():
 root.size=Vector2i(1920,1080);DisplayServer.window_set_size(root.size)
 var scene=load("res://gameplay/arsenal_review.tscn").instantiate();root.add_child(scene)
 for i in range(8):await process_frame
 var menu=scene.menu_panels;var builder=menu.builder
 expect(menu.title_art.texture is AtlasTexture,"Approved title visual loaded")
 expect(menu.title_art.position.y+menu.title_art.size.y<menu.tabs.battle_setup.position.y,"Title above navigation")
 await shot("menu_title")
 builder.config.attacker.faction="mercer";builder.config.attacker.units=[];builder.config.attacker.vehicles=[]
 for i in range(16):builder.config.attacker.units.append(builder.Config.unit())
 builder.changed();builder.open_fleet()
 var fleet=menu.get_node("VehicleFleet")
 await click(fleet.class_buttons.two_wheelers)
 expect(fleet.packing_hint.visible and "Up to 2" in fleet.packing_hint.text,"Default two-wheeler explanation")
 await click(fleet.model_buttons.ironhorse.button);await click(fleet.model_buttons.ironhorse.button)
 expect(fleet.convoy_row.cells[0].get_child_count()>2,"Two images fill first slot")
 expect(fleet.Formation.slots(fleet.selected,"mercer").size()==1,"Two click selections occupy one slot")
 await shot("two_bike_rule")
 for faction in ["stateline","blacktop","zangyaku","bitian","nbpd","trc"]:
  fleet.faction_id=faction;fleet.selected=[];fleet.refresh_models();fleet.refresh_convoy()
  for i in range(3):await process_frame
  expect(fleet.packing_hint.visible and "Up to 4" in fleet.packing_hint.text,"Bonus explanation "+faction)
  for i in range(4):await click(fleet.model_buttons.ironhorse.button)
  expect(fleet.selected==["ironhorse","ironhorse","ironhorse","ironhorse"] and fleet.Formation.slots(fleet.selected,faction).size()==1,"Four clicked bikes in one slot "+faction)
 await shot("four_bike_rule")
 await click(fleet.class_buttons.passenger_cars)
 expect(not fleet.packing_hint.visible,"Explanation hidden outside Two-Wheelers")
 fleet.queue_free();await process_frame
 root.size=Vector2i(1280,720);DisplayServer.window_set_size(root.size)
 await shot("menu_title_1280")
 var result={"checks":checks,"errors":errors}
 FileAccess.open(out+"ui.json",FileAccess.WRITE).store_string(JSON.stringify(result,"\t"));print("BIKE_UI_CHECK ",JSON.stringify(result));quit(0 if errors.is_empty() else 1)

motion.gd:
extends SceneTree
const Maps=preload("res://gameplay/sandbox_map_catalog.gd")
const Config=preload("res://gameplay/sandbox_force_config.gd")
const Estate=preload("res://gameplay/estate_battle_setup.gd")
const Body=preload("res://battle/vehicles/battle_vehicle_body_service.gd")
var errors=[]
var runs=[]
func _initialize():call_deferred("run")
func run():
 var scene=load("res://gameplay/arsenal_review.tscn").instantiate();root.add_child(scene);await process_frame;scene.set_process(false)
 var legacy=GDScript.new();legacy.source_code=JSON.parse_string(FileAccess.get_file_as_string("res://tools/bike_slots_20260915/source_before.json"))["gameplay/estate_battle_setup.gd"]
 assert(legacy.reload()==OK)
 for count in [0,2,4,12]:
  var c=Maps.preset("whittaker_estate");c.attacker.faction="mercer" if count==2 else "stateline";c.attacker.units=[];c.attacker.vehicles=[];c.attacker.erase("vehicle_occupants")
  for i in range(16):c.attacker.units.append(Config.unit(Config.CLASSES[i%5]))
  for i in range(count):c.attacker.vehicles.append("ironhorse")
  if count<12:c.attacker.vehicles.append_array(["bayou","shuttle"])
  await scene.start_battle(false,c)
  if scene.battle==null:errors.append("Launch "+str(count)+" "+scene.note.text);continue
  for i in range(12):await process_frame
  var view=scene.runtime.get_node("TacticalBattleView");var vehicles=[];var pairs=0;var overlaps=[]
  for v in scene.battle.vehicles.values():
   if v.side_id==scene.battle.attacker_side_id:
    vehicles.append(v)
    if not v.has_battle_position:errors.append("Unplaced vehicle "+str(count)+" "+v.battle_vehicle_id+" "+scene.note.text)
  if not view.battle_presentation.last_path_errors.is_empty():errors.append("Dismount paths "+str(count))
  for frame in range(30,361):
   var clock=frame/30.;var polys=[]
   for v in vehicles:
    var stop=view.battle_presentation.vehicle_stop_time(v);var pose=Estate.arrival_pose(v,clock,stop)
    polys.append(Body.corners_for_pose(pose.position,pose.facing,Body.profile_for_vehicle(v)))
    if count==0 and pose!=legacy.arrival_pose(v,clock,stop):errors.append("Non-bike arrival changed at "+str(clock))
   for i in range(vehicles.size()):
    for j in range(i+1,vehicles.size()):
     pairs+=1
     var hits=Geometry2D.intersect_polygons(polys[i],polys[j])
     if not hits.is_empty():
      var area=0.
      for polygon in hits:
       var a=0.
       for k in range(polygon.size()):a+=polygon[k].cross(polygon[(k+1)%polygon.size()])
       area+=absf(a)*.5
      if area>.02 and overlaps.size()<12:overlaps.append({"time":clock,"pair":[i,j],"area":area})
  if not overlaps.is_empty():errors.append("Arrival overlap: "+str(count)+" bikes")
  runs.append({"bikes":count,"pair_samples":pairs,"overlaps":overlaps})
  scene.return_to_setup();await process_frame
 var result={"errors":errors,"runs":runs}
 FileAccess.open("res://tools/bike_slots_20260915/motion.json",FileAccess.WRITE).store_string(JSON.stringify(result,"\t"));print("BIKE_MOTION_CHECK ",JSON.stringify(result));quit(0 if errors.is_empty() else 1)

